import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('reports a thrown string with its cause while preserving the caller rejection [specs/hal-engine-config-hooks/spec.md#8]', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const failures: Error[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'Test assistant'}),
    undefined,
    {
      hooks: {
        beforeModelResponse: async () => {
          throw 'hook failed';
        },
        onError: async (_session, error) => {
          failures.push(error);
        },
      },
    }
  );

  const outcome = await orchestrator.processMessage(session).then(
    value => ({resolved: value}),
    (reason: unknown) => ({rejected: reason})
  );

  expect({
    outcome,
    count: failures.length,
    isError: failures[0] instanceof Error,
    message: failures[0]?.message,
    cause: failures[0]?.cause,
  }).toEqual({
    outcome: {rejected: 'hook failed'},
    count: 1,
    isError: true,
    message: 'hook failed',
    cause: 'hook failed',
  });
});
EOF
 timeout 300 node --experimental-vm-modules node_modules/jest/bin/jest.js --runInBand --runTestsByPath src/orchestration/chatOrchestrator.rejection.test.ts"
